+// Tidal Metals fork: parse what MQTT_CONTROL just received, in this call. Upstream parsed it only at the start
+// of the next call, so every incoming message (a command, a PUBACK) waited one extra call before its callback
+// or state change. Same steps as at the start of step 40; the next call's parse finds nothing left.
+IF step = 40 AND COM.R_BUF.SIZE > 0 AND MQTT_INFO.MQTT_CONNECTED AND NOT DoDisconnect AND COM.ERROR_T = BYTE#0 THEN
+	IF PublishSplited THEN
+		MergeSplitedPublish(MQTT_IN_OUT:= ADR(MQTT_IN_OUT));
+	END_IF
+	ParseIncoming(MQTT_IN_OUT:= ADR(MQTT_IN_OUT));
+	ProfileMark(section := PROFILE_SECTION.PARSE_IN);
+END_IF
